const items = $input.all();

if (items.length <= 1) {
  return items;
}

// Identify the timestamp column
const getTimestamp = (item) => {
  const value =
    item.json.Timestamp ??
    item.json.timestamp ??
    item.json['Submitted At'];

  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : null;
};

// Sort newest first
const sorted = [...items].sort((a, b) => {
  return (getTimestamp(b) ?? 0) - (getTimestamp(a) ?? 0);
});

// Return only the newest row
return [sorted[0]];

const items = $input.all();

return items.map(item => {
  const raw = item.json.output;

  if (typeof raw !== 'string' || !raw.trim()) {
    throw new Error('LLM response is empty or missing.');
  }

  // Find the JSON object inside the response
  const start = raw.indexOf('{');

  if (start === -1) {
    throw new Error(
      'No opening JSON brace found. Actual response: ' +
      raw.slice(0, 500)
    );
  }

  // Extract everything from the first opening brace
  let jsonText = raw.slice(start).trim();

  // Remove Markdown code fences
  jsonText = jsonText
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();

  // Fix the LLM's invalid backticks around the subject
  jsonText = jsonText.replace(
    /("email_subject"\s*:\s*)`([^`]+)`/,
    (match, prefix, subject) =>
      prefix + JSON.stringify(subject.replace(/^["']|["']$/g, ''))
  );

  // Remove trailing commas
  jsonText = jsonText.replace(/,\s*([}\]])/g, '$1');

  let campaign;

  try {
    campaign = JSON.parse(jsonText);
  } catch (error) {
    throw new Error(
      'JSON parsing failed: ' + error.message +
      '\nResponse beginning: ' + jsonText.slice(0, 700)
    );
  }

  if (
    typeof campaign.email_subject !== 'string' ||
    typeof campaign.email_html !== 'string'
  ) {
    throw new Error('Required email fields are missing.');
  }

  return {
    json: {
      email_subject: campaign.email_subject,
      email_html: campaign.email_html,
      generation_status: 'success'
    }
  };
});
